head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil70602";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil70602.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb23", attr: "label", fn: function () { return String(dma_readDataVO.get("lpHdQty")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_listBzTpCd", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '701'); } }, { id: "tr_84", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '701'); } }, { id: "tr_97", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '701'); } }, { id: "tr_102", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '701'); } }, { id: "if_listBzTpCd_2", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702'); } }, { id: "tr_115", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702'); } }, { id: "tr_130", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702'); } }, { id: "tr_139", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702'); } }, { id: "if_listBzTpCd_3", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '703'); } }, { id: "tr_152", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '703'); } }, { id: "tr_165", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '703'); } }, { id: "if_listBzTpCd_4", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }, { id: "tr_173", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }, { id: "tr_186", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    scwin.cal();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil70602c.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name __ev_2_btn_Search_onclick
 * @description __ev_2_btn_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_2_btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70602.__ev_2_btn_Search_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_EtnChangePage
 * @description Etn Change Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_EtnChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnChangePage",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_EtnChangePageReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_loadListReq",
        target: "dlt_distrTp=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name etnChangePage
 * @description etn Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnChangePage = async function (tab) {
    scwin.form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_EtnChangePageReq').get('lastSaveStatCd'));
    if (tab === 1) {
        return;
    } else {
        if (tab === 2) {
            $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewIsurTab');
        } else {
            if (tab === 3) {
                $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewSrtyLpTab');
            } else {
                $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'EtnList.do';
    await scwin.tx_fn_EtnChangePage();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent('dma_EtnChangePageReq').set('listBzTpCd', "");
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name cal
 * @description cal 처리
 * @returns {void}
 * @hidden N
 */
scwin.cal = function () {
    $c.util.getComponent('txt_declSpd').setLabel($c.num.formatNumber(String($c.util.getComponent('txt_declSpd').getValue())));
};
